// Funktion zum Überprüfen der Webcam-Berechtigungen
function checkWebcamPermissions() {
    return new Promise((resolve, reject) => {
        navigator.mediaDevices.getUserMedia({ video: true })
            .then(stream => {
                // Wenn die Berechtigung erteilt wurde, den Stream verwenden oder verarbeiten
                resolve(true);
            })
            .catch(err => {
                // Bei Verweigerung der Berechtigung oder einem Fehler
                resolve(false);
            });
    });
}

